import {FABRICS,DESIGNS,DEFAULTS,normalizePreferences,estimate,preferenceSummary,createOrder,orderMessage} from './core.mjs';
import {drawCurtains} from './renderer.mjs';
const $=id=>document.getElementById(id),canvas=$('curtain-canvas'),config=window.lithosCurtainConfig||{},textures=new Map();
let preferences=structuredClone(DEFAULTS),photo=null,photoBlob=null,photoUrl='',isSample=true,showDesign=true,filter='all',editing=false,revision=0,currentOrder=null,reference='',drag=null;
const status=(message,error=false)=>{$('studio-status').textContent=message;$('studio-status').classList.toggle('error',error);};
const orderStatus=(message,error=false)=>{$('order-status').textContent=message;$('order-status').classList.toggle('error',error);};
const ref=()=> 'LC-'+new Date().toISOString().slice(0,10).replaceAll('-','')+'-'+[...crypto.getRandomValues(new Uint8Array(6))].map(v=>v.toString(16).padStart(2,'0')).join('').toUpperCase();
const revoke=url=>{if(url?.startsWith('blob:'))URL.revokeObjectURL(url);};
const imageFrom=url=>new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('ფოტო ვერ ჩაიტვირთა.'));img.src=url;});
const dataUrl=blob=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('ფოტო ვერ გაიხსნა.'));reader.readAsDataURL(blob);});
const blobFromCanvas=(type='image/jpeg',quality=.88)=>new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(Error('ესკიზის შენახვა ვერ მოხერხდა.')),type,quality));
function save(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>revoke(url),10000);}
function invalidateOrder(){currentOrder=null;reference='';$('order-ready').hidden=true;$('whatsapp-fallback').removeAttribute('href');orderStatus('');}
function updateFrame(){const b=preferences.box;const frame=$('window-frame');frame.hidden=!editing;frame.style.left=b.x*100+'%';frame.style.top=b.y*100+'%';frame.style.width=b.w*100+'%';frame.style.height=b.h*100+'%';for(const key of ['x','y','w','h'])$('box-'+key).value=Math.round(b[key]*100);}
function render(){
 if(photo){drawCurtains(canvas,photo,preferences,textures,showDesign);$('drop-zone').style.aspectRatio=photo.width+'/'+photo.height;}
 updateFrame();$('opening-value').textContent=Math.round(preferences.opening)+'%';
 const fabric=FABRICS.find(f=>f.id===preferences.fabric),design=DESIGNS.find(d=>d.id===preferences.design),info=estimate(preferences);
 $('summary-title').textContent=design.name+' / '+fabric.name.replace(/.* - /,'');$('summary-details').textContent=preferenceSummary(preferences).slice(2).join(' · ');
 $('dimension-note').textContent='გაშლილი ქსოვილის სავარაუდო სიგანე: '+info.spreadWidthM+' მ.'+(info.heightWarning?' არჩეული სიმაღლე აღემატება მომწოდებლის მითითებულ '+info.fabricMaxHeightCm+' სმ-ს — საჭიროა შეთანხმება.':'');
 $('sheer-wrap').hidden=preferences.design!=='layered';
}
function selectedFabricInfo(){
 const f=FABRICS.find(f=>f.id===preferences.fabric),box=$('selected-fabric');box.replaceChildren();const title=document.createElement('h4');title.textContent=f.name;
 const p=document.createElement('p');p.textContent=(f.kind==='sheer'?'თხელი / დღის ფარდა':'სქელი / ღამის ფარდა')+' · '+f.composition+' · მითითებული მაქს. სიმაღლე '+f.maxHeightCm+' სმ';
 const a=document.createElement('a');a.href=f.sourceUrl;a.target='_blank';a.rel='noopener noreferrer';a.textContent='მოდელი მომწოდებლის კატალოგში ↗';box.append(title,p,a);
}
function chooseFabric(id){preferences.fabric=id;invalidateOrder();renderFabrics();selectedFabricInfo();render();}
function renderFabrics(){
 const q=$('fabric-search').value.trim().toLocaleLowerCase('ka-GE');const list=FABRICS.filter(f=>(filter==='all'||f.kind===filter)&&(f.name.toLocaleLowerCase('ka-GE').includes(q)||f.id.includes(q)));
 $('fabric-options').replaceChildren(...list.map(f=>{const b=document.createElement('button');b.type='button';b.className='fabric-card'+(f.id===preferences.fabric?' selected':'');b.setAttribute('aria-pressed',String(f.id===preferences.fabric));b.setAttribute('aria-label',f.name);b.title=f.name;const img=document.createElement('img');img.src=f.image;img.alt=f.name+' — მომწოდებლის ფოტო';img.loading='lazy';img.width=160;img.height=160;const text=document.createElement('span');text.textContent=({wiens:'Wiens',tivit:'Tivit','soft-velvet':'Soft Micro',basel:'Basel',elegant:'Elegant',crepe:'კრეპი',romilda:'Romilda',royal:'Royal'}[f.id]);b.append(img,text);b.addEventListener('click',()=>{chooseFabric(f.id);$('fabric-options').querySelector('[aria-pressed="true"]')?.focus({preventScroll:true});});return b;}));
 if(!list.length){const p=document.createElement('p');p.textContent='ქსოვილი ვერ მოიძებნა.';p.className='small-note';$('fabric-options').append(p);}
}
function icon(id){
 const paths={wave:'M5 7 Q10 0 15 7 T25 7 T35 7 T45 7 M5 7V36M15 7V36M25 7V36M35 7V36M45 7V36',pencil:'M4 4H46 M7 4V36M12 4V36M17 4V36M22 4V36M27 4V36M32 4V36M37 4V36M42 4V36',pinch:'M4 3H46 M9 3L5 10L9 15L13 10Z M25 3L21 10L25 15L29 10Z M41 3L37 10L41 15L45 10Z M9 15L5 36M25 15V36M41 15L45 36',eyelet:'M3 7H47 M8 13V36M19 13V36M30 13V36M41 13V36 M8 3a4 4 0 1 0 .1 0M19 3a4 4 0 1 0 .1 0M30 3a4 4 0 1 0 .1 0M41 3a4 4 0 1 0 .1 0',roman:'M6 2H44V36H6Z M6 10H44M6 18H44M6 26H44',layered:'M3 3H47 M4 3V36H15L11 20L15 3 M46 3V36H35L39 20L35 3 M19 3V36M25 3V36M31 3V36'};
 const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 50 40');svg.setAttribute('aria-hidden','true');const path=document.createElementNS(svg.namespaceURI,'path');path.setAttribute('d',paths[id]);svg.append(path);return svg;
}
function renderDesigns(){
 $('design-options').replaceChildren(...DESIGNS.map(d=>{const b=document.createElement('button');b.type='button';b.className='design-card'+(preferences.design===d.id?' selected':'');b.setAttribute('aria-pressed',String(preferences.design===d.id));b.title=d.description;const text=document.createElement('span');text.textContent=d.name;b.append(icon(d.id),text);b.addEventListener('click',()=>{preferences.design=d.id;preferences.fullness=d.fullness;$('fullness').value=String(d.fullness);invalidateOrder();renderDesigns();render();$('design-options').querySelector('[aria-pressed="true"]')?.focus({preventScroll:true});});return b;}));
}
for(const button of document.querySelectorAll('[data-filter]'))button.addEventListener('click',()=>{filter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});renderFabrics();});
$('fabric-search').addEventListener('input',renderFabrics);
for(const f of FABRICS.filter(f=>f.kind==='sheer'))$('sheer-select').append(new Option(f.name,f.id));$('sheer-select').value=preferences.sheer;
for(const [id,key] of [['opening','opening'],['sheer-select','sheer'],['mount','mount'],['length','length'],['width-cm','widthCm'],['height-cm','heightCm'],['fullness','fullness'],['color-wish','colorWish']])$(id).addEventListener(id==='opening'?'input':'change',event=>{
 const raw={...preferences,[key]:event.target.value};try{preferences=normalizePreferences(raw);event.target.removeAttribute('aria-invalid');invalidateOrder();render();status('');}catch(error){event.target.setAttribute('aria-invalid','true');status(error.message,true);}
});
function setView(show){showDesign=show;$('show-original').setAttribute('aria-pressed',String(!show));$('show-design').setAttribute('aria-pressed',String(show));render();}
$('show-original').addEventListener('click',()=>setView(false));$('show-design').addEventListener('click',()=>setView(true));
$('fit-window').addEventListener('click',()=>{editing=!editing;$('fit-window').setAttribute('aria-pressed',String(editing));$('placement-details').open=editing;updateFrame();});
function clampBox(b){b={...b};b.x=Math.max(0,Math.min(.9,b.x));b.y=Math.max(0,Math.min(.9,b.y));b.w=Math.max(.1,Math.min(1-b.x,b.w));b.h=Math.max(.1,Math.min(1-b.y,b.h));return b;}
for(const key of ['x','y','w','h'])$('box-'+key).addEventListener('input',event=>{preferences.box=clampBox({...preferences.box,[key]:Number(event.target.value)/100});invalidateOrder();render();});
$('window-frame').addEventListener('pointerdown',event=>{if(!editing)return;event.preventDefault();const bounds=$('drop-zone').getBoundingClientRect();drag={pointer:event.pointerId,startX:event.clientX,startY:event.clientY,bounds,box:{...preferences.box},handle:event.target.dataset.handle||'move'};$('window-frame').setPointerCapture(event.pointerId);});
$('window-frame').addEventListener('pointermove',event=>{if(!drag||event.pointerId!==drag.pointer)return;const dx=(event.clientX-drag.startX)/drag.bounds.width,dy=(event.clientY-drag.startY)/drag.bounds.height,b={...drag.box};if(drag.handle==='move'){b.x=Math.max(0,Math.min(1-b.w,b.x+dx));b.y=Math.max(0,Math.min(1-b.h,b.y+dy));}else if(drag.handle==='se'){b.w+=dx;b.h+=dy;}else{const right=b.x+b.w,bottom=b.y+b.h;b.x=Math.max(0,Math.min(right-.1,b.x+dx));b.y=Math.max(0,Math.min(bottom-.1,b.y+dy));b.w=right-b.x;b.h=bottom-b.y;}preferences.box=clampBox(b);invalidateOrder();render();});
for(const type of ['pointerup','pointercancel'])$('window-frame').addEventListener(type,()=>drag=null);
for(const b of document.querySelectorAll('[data-handle]'))b.addEventListener('keydown',event=>{const delta={ArrowLeft:[-.01,0],ArrowRight:[.01,0],ArrowUp:[0,-.01],ArrowDown:[0,.01]}[event.key];if(!delta)return;event.preventDefault();const box={...preferences.box};if(b.dataset.handle==='se'){box.w+=delta[0];box.h+=delta[1];}else{box.x+=delta[0];box.y+=delta[1];box.w-=delta[0];box.h-=delta[1];}preferences.box=clampBox(box);invalidateOrder();render();});
async function preparePhoto(file){
 if(!['image/jpeg','image/png','image/webp'].includes(file.type)||!file.size||file.size>15*1024*1024)throw Error('აირჩიე JPEG, PNG ან WebP ფოტო, მაქსიმუმ 15 მბ.');
 let bitmap;try{bitmap=await createImageBitmap(file);}catch{throw Error('ფოტო ვერ გაიხსნა. სცადე სხვა ფაილი.');}
 try{if(bitmap.width*bitmap.height>50_000_000||!bitmap.width||!bitmap.height)throw Error('ფოტოს გარჩევადობა ძალიან დიდია.');const scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),temp=document.createElement('canvas');temp.width=Math.round(bitmap.width*scale);temp.height=Math.round(bitmap.height*scale);const ctx=temp.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,temp.width,temp.height);ctx.drawImage(bitmap,0,0,temp.width,temp.height);const blob=await new Promise(resolve=>temp.toBlob(resolve,'image/jpeg',.86));if(!blob||blob.size>2*1024*1024)throw Error('ფოტო ვერ შემცირდა. სცადე სხვა ფოტო.');return blob;}finally{bitmap.close();}
}
async function acceptPhoto(file){const thisRevision=++revision;status('მიმდინარეობს ფოტოს მომზადება…');try{const blob=await preparePhoto(file),url=URL.createObjectURL(blob),img=await imageFrom(url);if(thisRevision!==revision){revoke(url);return;}revoke(photoUrl);photoBlob=blob;photoUrl=url;photo=img;isSample=false;showDesign=true;preferences.box={x:.2,y:.1,w:.6,h:.75};invalidateOrder();$('photo-label').textContent='შენი ფანჯრის ფოტო';$('canvas-note').textContent='შენი ფოტო · ფარდის 2D ესკიზი. მოარგე მონიშნული არე ფანჯარას; ქსოვილის ტონი და ფაქტურა მიახლოებითია.';setView(true);status('ფოტო მზადაა · '+Math.round(blob.size/1024)+' კბ. ახლა მოარგე ფარდა შენს ფანჯარას.');}catch(error){if(thisRevision===revision)status(error.message,true);}}
$('upload-photo').addEventListener('click',()=>$('photo-input').click());$('camera-photo').addEventListener('click',()=>$('camera-input').click());
for(const id of ['photo-input','camera-input'])$(id).addEventListener('change',event=>{if(event.target.files[0])acceptPhoto(event.target.files[0]);event.target.value='';});
for(const type of ['dragover','dragenter'])$('drop-zone').addEventListener(type,event=>{event.preventDefault();$('drop-zone').classList.add('dragging');});for(const type of ['drop','dragleave'])$('drop-zone').addEventListener(type,event=>{event.preventDefault();$('drop-zone').classList.remove('dragging');if(type==='drop'&&event.dataTransfer.files[0])acceptPhoto(event.dataTransfer.files[0]);});
async function loadSample(){const thisRevision=++revision;try{const img=await imageFrom('assets/sample-window.webp');if(thisRevision!==revision)return;revoke(photoUrl);photoUrl='';photo=img;photoBlob=null;isSample=true;preferences.box={...DEFAULTS.box};invalidateOrder();$('photo-label').textContent='სადემონსტრაციო ფანჯარა';$('canvas-note').textContent='სადემონსტრაციო ინტერიერი · 2D ესკიზი, ქსოვილის მიახლოებითი ტონითა და ფაქტურით.';render();}catch(error){status(error.message,true);}}
$('reset-photo').addEventListener('click',()=>{$('order-form').reset();editing=false;$('fit-window').setAttribute('aria-pressed','false');loadSample();status('ფოტო წაშლილია. ნაჩვენებია სადემონსტრაციო ნიმუში.');});
$('download-preview').addEventListener('click',async()=>{if(!photo)return;try{drawCurtains(canvas,photo,preferences,textures,true);save(await blobFromCanvas(),'lithos-curtain-2D-'+(reference||ref())+'.jpg');if(!showDesign)render();status('ესკიზის ჩამოტვირთვა დაწყებულია.');}catch(error){status(error.message,true);}});
async function projectData(){if(!photo)throw Error('ჯერ ატვირთე ფოტო.');drawCurtains(canvas,photo,preferences,textures,true);const preview=await blobFromCanvas();if(!showDesign)render();return {version:1,reference:reference||ref(),createdAt:new Date().toISOString(),source:isSample?'sample':'customer-photo',mode:'2d-concept',preferences:normalizePreferences(preferences),original:photoBlob?await dataUrl(photoBlob):null,preview:await dataUrl(preview),fabricSource:FABRICS.find(f=>f.id===preferences.fabric).sourceUrl,submitted:false};}
$('save-project').addEventListener('click',async()=>{try{save(new Blob([JSON.stringify(await projectData(),null,2)],{type:'application/json'}),'lithos-curtain-project.json');status('პროექტის ჩამოტვირთვა დაწყებულია.');}catch(error){status(error.message,true);}});
for(const d of document.querySelectorAll('dialog')){d.querySelector('[data-close]').addEventListener('click',()=>d.close());d.addEventListener('click',event=>{if(event.target!==d)return;const r=d.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)d.close();});}
for(const b of document.querySelectorAll('[data-privacy]'))b.addEventListener('click',()=>$('privacy-dialog').showModal());
$('start-order').addEventListener('click',()=>{
 if(!photo||isSample){status('შეკვეთამდე ატვირთე შენი ფანჯრის ფოტო. ნიმუში მხოლოდ დიზაინის გასაცნობადაა.',true);$('upload-photo').focus({preventScroll:true});$('upload-photo').scrollIntoView({block:'center',behavior:'smooth'});return;}
 if(document.querySelector('[aria-invalid="true"]')){status('შეკვეთამდე გაასწორე მონიშნული ზომები.',true);return;}
 reference=reference||ref();$('order-detail').textContent='პროექტი '+reference+' · '+preferenceSummary(preferences).join(' · ')+' · საწყისი ფოტო და 2D ესკიზი WhatsApp-ში თავად უნდა დაურთო. ქსოვილის ზუსტი ვარიანტი, ფერი და დიზაინის შეკერვა დასაზუსტებელია.';orderStatus('');$('order-ready').hidden=true;$('order-dialog').showModal();
});
$('order-form').addEventListener('input',()=>{$('order-ready').hidden=true;currentOrder=null;$('whatsapp-fallback').removeAttribute('href');});
$('order-form').addEventListener('submit',event=>{
 event.preventDefault();try{if(isSample||!photoBlob)throw Error('შეკვეთას შენი ფანჯრის ფოტო სჭირდება.');const raw=Object.fromEntries(new FormData(event.target));currentOrder=createOrder(preferences,{...raw,consent:raw.consent==='on'},reference||ref());const phone=String(config.whatsappPhone||'').replace(/\D/g,'');if(!/^\d{8,15}$/.test(phone))throw Error('საკონტაქტო არხი არ არის გამართული.');const url='https://wa.me/'+phone+'?text='+encodeURIComponent(orderMessage(currentOrder));$('whatsapp-fallback').href=url;$('order-ready').hidden=false;window.open(url,'_blank','noopener,noreferrer');orderStatus('შეტყობინება მომზადებულია WhatsApp-ში. გაგზავნა თავად დაადასტურე და ფოტოები დაურთე. მიღებას აქ ვერ ვადასტურებთ.');}catch(error){orderStatus(error.message,true);}
});
$('download-original').addEventListener('click',()=>{if(currentOrder&&photoBlob)save(photoBlob,'lithos-'+currentOrder.reference+'-original.jpg');});
$('download-order').addEventListener('click',async()=>{if(!currentOrder)return;try{const data={...currentOrder,photos:await projectData(),submitted:false};save(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),'lithos-order-'+currentOrder.reference+'.json');orderStatus('მოთხოვნის ფაილის ჩამოტვირთვა დაწყებულია. ავტომატურად არ გაგზავნილა.');}catch(error){orderStatus(error.message,true);}});
$('share-photos').addEventListener('click',async()=>{if(!currentOrder||!photoBlob)return;try{drawCurtains(canvas,photo,preferences,textures,true);const preview=await blobFromCanvas(),files=[new File([photoBlob],currentOrder.reference+'-original.jpg',{type:'image/jpeg'}),new File([preview],currentOrder.reference+'-2D.jpg',{type:'image/jpeg'})];if(!navigator.canShare?.({files})||!navigator.share){save(preview,currentOrder.reference+'-2D.jpg');save(photoBlob,currentOrder.reference+'-original.jpg');orderStatus('მოწყობილობა ფაილების პირდაპირ გაზიარებას არ უჭერს მხარს. ორივე ფოტოს ჩამოტვირთვა დაწყებულია; დაურთე WhatsApp-ს.');return;}await navigator.share({files,title:'LITHOS / '+currentOrder.reference,text:orderMessage(currentOrder)});orderStatus('გაზიარების ფანჯარა დაიხურა. მიღება და საბოლოო გაგზავნა მიმღებთან გადაამოწმე.');}catch(error){orderStatus(error.name==='AbortError'?'გაზიარება გაუქმდა.':error.message,error.name!=='AbortError');}finally{render();}});
$('catalog-gallery').replaceChildren(...FABRICS.slice(0,4).map(f=>{const article=document.createElement('article');article.className='catalog-item';const img=document.createElement('img');img.src=f.image;img.alt=f.name+' — MeFarde.ge-ის ფოტო';img.width=360;img.height=330;img.loading='lazy';const title=document.createElement('h3');title.textContent=f.name;const p=document.createElement('p');p.textContent=(f.kind==='sheer'?'დღის ფარდა':'ღამის ფარდა')+' · მომწოდებელი: MeFarde.ge';const b=document.createElement('button');b.className='text-button';b.type='button';b.textContent='აირჩიე ეს ქსოვილი ↗';b.addEventListener('click',()=>{chooseFabric(f.id);$('studio').scrollIntoView({behavior:'smooth'});});const a=document.createElement('a');a.href=f.sourceUrl;a.target='_blank';a.rel='noopener noreferrer';a.textContent='წყარო ↗';article.append(img,title,p,b,a);return article;}));
renderFabrics();renderDesigns();selectedFabricInfo();render();loadSample();
for(const f of FABRICS)imageFrom(f.image).then(img=>{textures.set(f.id,img);if(f.id===preferences.fabric||f.id===preferences.sheer)render();}).catch(()=>{});
window.addEventListener('pagehide',()=>{++revision;revoke(photoUrl);photo=null;photoBlob=null;photoUrl='';currentOrder=null;$('order-form').reset();});
window.addEventListener('pageshow',event=>{if(event.persisted&&!photo)loadSample();});
